from pathlib import Path
import re, statistics
s=Path('tmp/pdfs/manuscript-plain.txt').read_text()
for page,stop in [(21,'Table 22:'),(22,'Table 24:')]:
 block=s.split('===== PAGE %d ====='%page)[1].split(stop)[0]
 metrics={k:[] for k in ['G-Eval','SEEval','CheckEval']}
 print('\\nPAGE',page)
 for ln in block.splitlines():
  if not any(k in ln for k in metrics): continue
  key=next(k for k in metrics if k in ln)
  nums=[float(n) for n in re.findall(r'(?<"'!['"\\d.])[-]?0\\.\\d{4}',ln)]
  if len(nums)==10:
   metrics[key].append(nums[-2:])
   if abs(sum(nums[:-2:2])/4-nums[-2])>0.0002 or abs(sum(nums[1:-2:2])/4-nums[-1])>0.0002:
    print('Mean mismatch:',ln)
    print('Computed',round(sum(nums[:-2:2])/4,5),round(sum(nums[1:-2:2])/4,5))
 for k,v in metrics.items():
  print(k,len(v),'average reported row means',[round(statistics.mean(x[i] for x in v),5) for i in range(2)])
PY"
